// The stroke order of the acts' one-character marks (STORYBOARD v2.3 §10-B), taken from KanjiVG.
//
//   node scripts/build-kanji-strokes.mjs <directory with KanjiVG's kanji/*.svg files>
//   → src/content/kanji-strokes.ts
//
// KanjiVG is © Ulrich Apel and its contributors, released under the Creative Commons
// Attribution-ShareAlike 3.0 licence. The generated file is therefore under the same licence (it
// says so in its header), and the site credits KanjiVG in its footer. The source files are not kept
// in this repository: get the eleven files (named by code point, e.g. 06398.svg) from the KanjiVG
// project and pass their directory.
import { readFileSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';

const dir = process.argv[2];
if (!dir) throw new Error('usage: node scripts/build-kanji-strokes.mjs <directory with KanjiVG kanji/*.svg>');
const ROOT = resolve(import.meta.dirname, '..');
const acts = readFileSync(join(ROOT, 'src/content/acts.ts'), 'utf8');
const kanji = [...new Set([...acts.matchAll(/kanji: '(.)'/gu)].map((m) => m[1]))];

const entries = kanji.map((k) => {
  const file = `${k.codePointAt(0).toString(16).padStart(5, '0')}.svg`;
  const svg = readFileSync(join(dir, file), 'utf8');
  // Strokes are the <path id="kvg:…-sN"> elements, in writing order.
  const strokes = [...svg.matchAll(/<path id="kvg:[0-9a-f]+-s(\d+)"[^>]*\sd="([^"]+)"/g)].sort((a, b) => Number(a[1]) - Number(b[1])).map((m) => m[2]);
  if (strokes.length === 0) throw new Error(`no strokes found in ${file}`);
  return `  ${JSON.stringify(k)}: ${JSON.stringify(strokes)},`;
});

writeFileSync(
  join(ROOT, 'src/content/kanji-strokes.ts'),
  `// Generated by scripts/build-kanji-strokes.mjs. Do not edit.
//
// Stroke paths (in writing order, viewBox 0 0 109 109) of the acts' one-character marks, from
// KanjiVG — © Ulrich Apel and contributors, Creative Commons Attribution-ShareAlike 3.0.
// This file is a derivative of that data and is licensed under the same terms (CC BY-SA 3.0).
export const KANJI_STROKES: Record<string, readonly string[]> = {
${entries.join('\n')}
};
`,
);
console.log(`kanji-strokes.ts: ${kanji.join('')} (${kanji.length} characters)`);
